# 单文件运行态投影：不改变原监控状态语义，只增加可观测字段。
_single_init_previous_status = ShukGuangYaDisk.api_organize_monitor_status


def _single_init_api_organize_monitor_status(self):
    response = _single_init_previous_status(self)
    if isinstance(response, dict):
        data = response.setdefault("data", {})
        status = data.setdefault("status", {})
        bundle_prefix = __name__ + "."
        loaded_bundle_modules = sum(
            1 for module_name in _bundle_sys.modules
            if module_name.startswith(bundle_prefix)
        )
        finder_count = sum(
            1 for finder in _bundle_sys.meta_path
            if getattr(finder, "_guangya_bundle_package", None) == __name__
        )
        status.update({
            "single_file_runtime": True,
            "runtime_layout": "single-init-bundled",
            "runtime_version": str(getattr(self, "plugin_version", "") or ""),
            "runtime_bundle_module_count": len(_BUNDLED_SOURCES),
            "runtime_loaded_bundle_module_count": loaded_bundle_modules,
            "runtime_finder_count": finder_count,
            "runtime_hot_reload_fence_ok": finder_count == 1,
        })
    return response


# 覆盖入口类 API 注册路径；运行期其它 MRO/补丁行为保持 3.9.0 原样。
ShukGuangYaDisk.api_organize_monitor_status = _single_init_api_organize_monitor_status
ShukGuangYaDisk.get_organizer_api = _single_init_get_organizer_api
ShukGuangYaDisk.plugin_version = "3.9.7"
ShukGuangYaDisk.single_file_runtime = True
ShukGuangYaDisk.runtime_layout = "single-init-bundled"

__all__ = ["ShukGuangYaDisk"]
